-- Fiche Le présent : pouvoir, vouloir, savoir, voir, prendre (CM1) - conjugaison, notion 'present'. Relancer ce script remplace le contenu de la fiche.
insert into contenu_cours (classe, matiere, titre, contenu, statut, notion_id)
select 'cm1', 'conjugaison', 'Le présent : pouvoir, vouloir, savoir, voir, prendre', $fiche$
