[titre]Prendre[/titre]
[table=2][cell bg=#classe border=#classe padding=10,4,10,4][center][color=white][/color][/center][/cell][cell bg=#classe border=#classe padding=10,4,10,4][center][color=white][b]prendre[/b][/color][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=22][b]je[/b][/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=22]prends[/font_size][/center][/cell][cell bg=#FFD49A border=#F2A541 padding=10,4,10,4][center][font_size=22][b]tu[/b][/font_size][/center][/cell][cell bg=#FFD49A border=#F2A541 padding=10,4,10,4][center][font_size=22]prends[/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=22][b]il, elle[/b][/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=22]prend[/font_size][/center][/cell][cell bg=#FFD49A border=#F2A541 padding=10,4,10,4][center][font_size=22][b]nous[/b][/font_size][/center][/cell][cell bg=#FFD49A border=#F2A541 padding=10,4,10,4][center][font_size=22]prenons[/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=22][b]vous[/b][/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=22]prenez[/font_size][/center][/cell][cell bg=#FFD49A border=#F2A541 padding=10,4,10,4][center][font_size=22][b]ils, elles[/b][/font_size][/center][/cell][cell bg=#FFD49A border=#F2A541 padding=10,4,10,4][center][font_size=22]prennent[/font_size][/center][/cell][/table]
[cadre=astuce]il pren[b]d[/b] (pas de t) ; ils pre[b]nn[/b]ent avec deux n. Pareil : apprendre, comprendre.[/cadre]
[page]
[titre]Ce qui revient souvent[/titre]
[cadre]• je, tu : terminaisons en [b]-s[/b] ou [b]-x[/b] : je sais, tu peux.
• il, elle : [b]-t[/b] ou [b]-d[/b] : il veut, il prend.
• ils, elles : [b]-ent[/b], souvent avec un radical qui change : ils peuvent, ils veulent.[/cadre]
[page]
[titre]Je retiens[/titre]
[cadre]• pouvoir : peux, peux, peut, pouvons, pouvez, peuvent.
• vouloir : veux, veux, veut, voulons, voulez, veulent.
• savoir : sais, sais, sait… ils savent. voir : vois… nous voyons, ils voient.
• prendre : prends, prends, prend, prenons, prenez, prennent.[/cadre]
$fiche$, 'publie', n.id from contenu_notions n where n.code = 'present'
on conflict (notion_id, classe) where statut <> 'archive'
do update set titre = excluded.titre, contenu = excluded.contenu, matiere = excluded.matiere, statut = 'publie', modifie_le = now()
returning id, classe, titre, statut;
